cflags_base = [
    "-nodefaults",
    "-i include",
    f"-i build/{config.version}/include",
]
cflags_z = [
    *cflags_base,  # the library flags
    "-O3",
    "-i include/zlib",
]
def ZLib(objects):
    return {
        "lib": "zlib",
        "cflags": cflags_z,
        "objects": objects,
    }
def Plain(lib_name, objects):
    return {
        "cflags": [*cflags_base, "-ipa file"],
        "objects": objects,
    }
config.libs = [
    {
        "lib": "rt",
        "cflags": cflags_base,
        "objects": [
            Object(Matching, "rt/a.c"),
        ],
    },
    ZLib(
        [
            Object(Matching, "zlib/b.c"),
            Object(NonMatching, "zlib/c.c", extra_cflags=["-i include/zextra"]),
        ],
    ),
    Plain(
        "os",
        [
            Object(Matching, "os/d.c", extra_cflags=cflags_z),
        ],
    ),
]

config.libs = [
    {
        "objects": [
            Object(Matching, "a/b.c"),
            Object(
                NonMatching,
                "a/c.cp",
                extra_cflags=["-x"],
            ),
            Object(Matching, "a/d.c", extra_cflags=["-char unsigned"]),
#   RVLSDKLib("os", [Object(NonMatching, "a/commented.c")]),
        ],
    },
]

