sources:
#define L2CAP_MIN_OFFSET 9
#define RFCOMM_PF_OFFSET 4
#define BTM_CLOCK_OFFSET_VALID 0x8000
#define RFCOMM_MIN_OFFSET 5
#define RFCOMM_DATA_OVERHEAD (RFCOMM_MIN_OFFSET + 1)
typedef unsigned char UINT8;
typedef unsigned short UINT16;
typedef struct { UINT16 offset; UINT16 len; } BUF;
int f(BUF* p_buf, int x, UINT16 clock) {
    p_buf->offset = L2CAP_MIN_OFFSET;
    x = (x & 0xf0) >> RFCOMM_PF_OFFSET;
    if (clock & BTM_CLOCK_OFFSET_VALID) { x = x + L2CAP_MIN_OFFSET; }
    p_buf->len = p_buf->len + L2CAP_MIN_OFFSET;
    p_buf->len -= RFCOMM_MIN_OFFSET;
    return x - RFCOMM_MIN_OFFSET + (int)sizeof(UINT8[L2CAP_MIN_OFFSET]);
}

